"use strict";(Array.isArray(self.webpackChunkwoocommerce_multivendor_marketplace_docs)?self.webpackChunkwoocommerce_multivendor_marketplace_docs:self.webpackChunkwoocommerce_multivendor_marketplace_docs=[]).push([[6349],{99262(e,t,n){n.r(t),n.d(t,{comp:()=>o,data:()=>r});var a=n(20641);const s=n.p+"assets/img/vendor-admin-news-detail-live.5eb2d412.png",i={},o=(0,n(66262).A)(i,[["render",function(e,t){return(0,a.uX)(),(0,a.CE)("div",null,t[0]||(t[0]=[(0,a.Fv)('<h1 id="admin-news-–-vendor" tabindex="-1"><a class="header-anchor" href="#admin-news-–-vendor"><span>Admin News – Vendor</span></a></h1><p>The <strong>Admin News</strong> section allows vendors to stay updated with important announcements shared by the marketplace admin.</p><div class="hint-container tip"><p class="hint-container-title">Administrator Guide</p><p>If you are a store administrator looking to create news posts, set expiration dates, or configure seller visibility, please refer to the <a href="/documentation/admin-news" target="_blank" rel="noopener noreferrer">Admin News Management</a> documentation.</p></div><hr><h2 id="access-path" tabindex="-1"><a class="header-anchor" href="#access-path"><span>Access Path</span></a></h2><p>Vendors can access marketplace announcements directly from their seller panel:</p><ol><li>Log in to the marketplace with your vendor account credentials.</li><li>In the vendor dashboard left navigation menu, navigate to <strong>News &amp; Notifications → Admin News</strong>.</li><li>You will arrive at the main <strong>Admin News</strong> feed page (<code>/seller/admin-news/</code>).</li></ol><p>Breadcrumb navigation:</p><ul><li><strong>Dashboard → News &amp; Notifications → Admin News</strong></li></ul><hr><h2 id="view-admin-news" tabindex="-1"><a class="header-anchor" href="#view-admin-news"><span>View Admin News</span></a></h2><ul><li>Vendors can view all the news sent by the admin from their vendor dashboard.</li><li>Only news assigned or made visible to vendors will appear, and vendors can click on any news item to read the full details.</li></ul><h3 id="admin-news-feed-interface" tabindex="-1"><a class="header-anchor" href="#admin-news-feed-interface"><span>Admin News Feed Interface</span></a></h3><p>The updated vendor panel presents announcements in an organized table with instant search capability.</p><h4 id="key-interface-elements" tabindex="-1"><a class="header-anchor" href="#key-interface-elements"><span>Key Interface Elements</span></a></h4><ul><li><strong>Search by News Title</strong>: A dedicated search input located at the top right of the table. Enter any keyword or title term (for example, &quot;Payouts&quot; or &quot;Policy&quot;) and press <strong>Enter</strong> to instantly filter matching news items.</li><li><strong>Helper Notice</strong>: A clear guideline reminding sellers: <em>&quot;Click on the news title to read a news.&quot;</em></li><li><strong>Structured News Table</strong>: Displays essential information at a glance:</li></ul><table><thead><tr><th style="text-align:left;">Column Name</th><th style="text-align:left;">Description</th><th style="text-align:left;">What Vendors See</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Title</strong></td><td style="text-align:left;">The headline of the announcement published by the admin.</td><td style="text-align:left;">A clickable link that opens the complete announcement article.</td></tr><tr><td style="text-align:left;"><strong>Description</strong></td><td style="text-align:left;">A brief preview or summary excerpt of the news post.</td><td style="text-align:left;">Gives vendors a quick overview before opening the full article. Ends with an ellipsis (<code>...</code>).</td></tr><tr><td style="text-align:left;"><strong>Published On</strong></td><td style="text-align:left;">The date when the administrator published the announcement.</td><td style="text-align:left;">Formatted clearly by month, day, and year (e.g., <em>October 3, 2026</em>).</td></tr></tbody></table><hr><h2 id="view-news-details" tabindex="-1"><a class="header-anchor" href="#view-news-details"><span>View News Details</span></a></h2><ul><li>By tapping on any news item, the vendor can view the complete description and details of that news.</li><li>This helps vendors stay informed about marketplace updates, policies, or announcements.</li></ul><p><a class="doc-image-link" href="./assets/vendor-admin-news-detail-live.png"><img src="'+s+'" alt="Vendor Admin News Detail View"></a></p><h3 id="news-detail-screen-elements" tabindex="-1"><a class="header-anchor" href="#news-detail-screen-elements"><span>News Detail Screen Elements</span></a></h3><p>When clicking any news headline from the table, a dedicated article card opens with the following details:</p><ul><li><strong>Back to News List Button (<code>←</code>)</strong>: Located beside the headline. Clicking this arrow icon returns you directly to the Admin News table without losing your position.</li><li><strong>Announcement Headline</strong>: Displayed prominently at the top of the reading card.</li><li><strong>Full Article Content</strong>: Displays the complete text provided by the marketplace administration, including: <ul><li>Detailed policy explanations and terms.</li><li>Important dates, schedules, or cut-off times.</li><li>Bulleted steps and operational instructions.</li><li>Hyperlinks to relevant dashboard sections (such as Payouts, Transactions, or Profile Settings).</li></ul></li></ul><hr><h2 id="step-by-step-vendor-workflow" tabindex="-1"><a class="header-anchor" href="#step-by-step-vendor-workflow"><span>Step-by-Step Vendor Workflow</span></a></h2><p>Following this standard process ensures you never miss critical marketplace updates:</p><ol><li><strong>Check the Admin News Section Regularly</strong>: When logging into your seller dashboard, check the <strong>Admin News</strong> section under <strong>News &amp; Notifications</strong> for new announcements.</li><li><strong>Scan Headlines and Dates</strong>: Review the <strong>Published On</strong> column and recent headlines to identify urgent notices or seasonal guidelines.</li><li><strong>Use the Title Search</strong>: If you are looking for a specific topic (such as payout dates, holiday hours, or commission updates), type the keyword into the <strong>Search by news title</strong> field.</li><li><strong>Read the Full Announcement</strong>: Click on the headline link to view the entire content.</li><li><strong>Return to News Feed</strong>: Click the <strong>Back (<code>←</code>)</strong> button next to the title or use the breadcrumbs to return to the news list.</li></ol><hr><h2 id="types-of-announcements-shared-by-admin" tabindex="-1"><a class="header-anchor" href="#types-of-announcements-shared-by-admin"><span>Types of Announcements Shared by Admin</span></a></h2><p>Marketplace administrators use Admin News to communicate essential business updates, such as:</p><ul><li><strong>Payout &amp; Commission Schedules</strong>: Information regarding payout dates, processing cycles, and withdrawal cutoff hours.</li><li><strong>Policy &amp; Agreement Updates</strong>: Revisions to marketplace seller terms, return policies, or vendor service level agreements (SLAs).</li><li><strong>Platform Features &amp; Tools</strong>: Announcements regarding new seller dashboard features, such as product comparison, vacation mode, or shipping integrations.</li><li><strong>Sales Campaigns &amp; Promotions</strong>: Invitations to join marketplace-wide seasonal sales (e.g., Autumn Sale, Black Friday, or Holiday fairs).</li><li><strong>Scheduled Maintenance Alerts</strong>: Advance notifications regarding technical maintenance windows or platform updates.</li></ul><hr>',33)]))}]]),r=JSON.parse('{"path":"/documentation/admin-news-vendor.html","title":"Admin News – Vendor Guide","lang":"en-US","frontmatter":{"title":"Admin News – Vendor Guide","description":"Complete user guide for vendors to view and track marketplace announcements, policy updates, and news published by the administrator in WooCommerce Multi-Vendor Marketplace.","head":[["meta",{"name":"keywords","content":"woocommerce marketplace vendor news, seller admin news, marketplace announcements, read admin news vendor dashboard, seller notification updates, vendor news feed woocommerce"}],["meta",{"property":"og:title","content":"Admin News – Vendor Guide | WooCommerce Multi-Vendor Marketplace"}],["meta",{"property":"og:description","content":"Complete user guide for vendors to view and track marketplace announcements, policy updates, and news published by the administrator in WooCommerce Multi-Vendor Marketplace."}],["meta",{"property":"og:type","content":"article"}]]},"headers":[{"level":2,"title":"Access Path","slug":"access-path","link":"#access-path","children":[]},{"level":2,"title":"View Admin News","slug":"view-admin-news","link":"#view-admin-news","children":[{"level":3,"title":"Admin News Feed Interface","slug":"admin-news-feed-interface","link":"#admin-news-feed-interface","children":[]}]},{"level":2,"title":"View News Details","slug":"view-news-details","link":"#view-news-details","children":[{"level":3,"title":"News Detail Screen Elements","slug":"news-detail-screen-elements","link":"#news-detail-screen-elements","children":[]}]},{"level":2,"title":"Step-by-Step Vendor Workflow","slug":"step-by-step-vendor-workflow","link":"#step-by-step-vendor-workflow","children":[]},{"level":2,"title":"Types of Announcements Shared by Admin","slug":"types-of-announcements-shared-by-admin","link":"#types-of-announcements-shared-by-admin","children":[]}],"git":{},"filePathRelative":"documentation/admin-news-vendor.md"}')}}]);